<script setup lang="ts">
import {shallowRef,ref,watch,onUnmounted} from 'vue';import {useApplication} from '../../application';import type {BodyHistory,BodyDetail,SetDetail} from '../../shared/api/minutes-inspection';import {ApiError} from '../../shared/api/client';
const props=defineProps<{meetingId:string;enabled:boolean;locked:boolean}>();const emit=defineEmits<{restore:[kind:'BODY'|'SET',id:string];denied:[cause:unknown]}>();const {minutesInspection,session}=useApplication();const kind=ref<'BODY'|'SET'>('BODY'),page=shallowRef<BodyHistory|null>(null),detail=shallowRef<BodyDetail|SetDetail|null>(null),error=ref(''),busy=ref(false),elementPage=ref(0);let epoch=0,controller:AbortController|null=null;
function clear(){epoch++;controller?.abort();page.value=null;detail.value=null;error.value='';busy.value=false;}
async function load(next:string|null=null){clear();if(!props.enabled)return;const turn=epoch,id=props.meetingId,request=new AbortController();controller=request;busy.value=true;try{const v=await minutesInspection.history(id,kind.value,next,request.signal);if(turn===epoch)page.value=v;}catch(cause){if(turn===epoch){if(cause instanceof ApiError&&[401,403].includes(cause.status)){clear();emit('denied',cause);}error.value=cause instanceof Error?cause.message:'历史暂不可用。';}}finally{if(turn===epoch)busy.value=false;}}
async function inspect(id:string){const turn=++epoch;elementPage.value=0;controller?.abort();const request=new AbortController();controller=request;detail.value=null;busy.value=true;try{const v=kind.value==='BODY'?await minutesInspection.body(props.meetingId,id,request.signal):await minutesInspection.set(props.meetingId,id,request.signal);if(turn===epoch)detail.value=v;}catch(cause){if(turn===epoch){if(cause instanceof ApiError&&[401,403].includes(cause.status)){clear();emit('denied',cause);}error.value=cause instanceof Error?cause.message:'历史内容暂不可用。';}}finally{if(turn===epoch)busy.value=false;}}
watch(()=>[props.meetingId,props.enabled,session.current.value?.actor.enterpriseId],clear,{flush:'sync'});onUnmounted(clear);
</script>
<template><section><h3>已保存版本</h3><p>正文与要素集合分别保存和恢复。恢复会创建新版本，审阅需重新核对。</p><select v-model="kind" @change="clear"><option value="BODY">正文历史</option><option value="SET">要素集合历史</option></select><button class="btn" :disabled="busy||!enabled" @click="load()">读取历史</button><ul v-if="page"><li v-for="item in page.items" :key="item.id">版本 {{item.revisionToken}} · {{item.createdAt}} <button class="btn" @click="inspect(item.id)">查看</button></li></ul><button v-if="page?.hasMore" class="btn" :disabled="busy" @click="load(page.nextBeforeRevisionToken)">下一页</button><article v-if="detail"><template v-if="'body' in detail"><h4>{{detail.body.title}}</h4><pre>{{detail.body.body}}</pre><button class="btn" :disabled="locked" @click="emit('restore','BODY',detail.body.id)">恢复此正文</button></template><template v-else><div v-for="(items,category) in detail.elements" :key="category"><h4>{{category}}</h4><p v-for="item in items.slice(elementPage*20,(elementPage+1)*20)" :key="item.id">{{item.body}}</p><p>本类共 {{items.length}} 项。</p></div><button class="btn" :disabled="elementPage===0" @click="elementPage--">上一页要素</button><button class="btn" :disabled="!Object.values(detail.elements).some(x=>(elementPage+1)*20<x.length)" @click="elementPage++">下一页要素</button><button class="btn" :disabled="locked" @click="emit('restore','SET',detail.set.id)">恢复此要素集合</button></template></article><p v-if="error" role="alert">{{error}}</p></section></template>
<style scoped>section{margin-top:24px}button,select{margin:6px}li{margin:8px 0}pre{white-space:pre-wrap;max-height:360px;overflow:auto}article{border:1px solid var(--border);padding:14px}</style>
